"""Data-quality rules for one partner shipment row. Each rule: a row that breaks it, and a row that passes."""
import unittest

from shipment_import.rules import check_row


class RowRules(unittest.TestCase):
    def test_good_row_passes(self):
        self.assertEqual(check_row({"shipment_id": "SHP-0001", "weight_kg": "12.5"}), [])

    def test_blank_shipment_id(self):
        # a row with an empty shipment_id is rejected as `shipment_id_missing`
        self.assertEqual(check_row({"shipment_id": "", "weight_kg": "1"}), ["shipment_id_missing"])

    def test_whitespace_only_shipment_id(self):
        # a shipment_id of only spaces is as empty as "" -> `shipment_id_missing`
        self.assertEqual(check_row({"shipment_id": "   ", "weight_kg": "1"}), ["shipment_id_missing"])

    def test_absent_shipment_id_column_value(self):
        # csv.DictReader gives None for a short row -> `shipment_id_missing`
        self.assertEqual(check_row({"shipment_id": None, "weight_kg": "1"}), ["shipment_id_missing"])

    def test_negative_weight(self):
        # weight_kg = -3.2 is rejected as `weight_kg_out_of_range`
        self.assertEqual(check_row({"shipment_id": "A", "weight_kg": "-3.2"}), ["weight_kg_out_of_range"])

    def test_zero_weight(self):
        # weight_kg = 0 is rejected as `weight_kg_out_of_range` (rule is weight_kg > 0)
        self.assertEqual(check_row({"shipment_id": "A", "weight_kg": "0"}), ["weight_kg_out_of_range"])

    def test_smallest_positive_weight_passes(self):
        self.assertEqual(check_row({"shipment_id": "A", "weight_kg": "0.001"}), [])

    def test_blank_weight(self):
        # an empty weight_kg is rejected as `weight_kg_missing`
        self.assertEqual(check_row({"shipment_id": "A", "weight_kg": ""}), ["weight_kg_missing"])

    def test_non_numeric_weight(self):
        # weight_kg = "12kg" is rejected as `weight_kg_not_a_number`, not coerced
        self.assertEqual(check_row({"shipment_id": "A", "weight_kg": "12kg"}), ["weight_kg_not_a_number"])

    def test_nan_and_infinity_weight(self):
        # "NaN" / "inf" parse as floats but are not weights -> `weight_kg_not_a_number`
        for value in ("NaN", "inf", "-Infinity"):
            self.assertEqual(check_row({"shipment_id": "A", "weight_kg": value}), ["weight_kg_not_a_number"], value)

    def test_every_broken_rule_is_reported(self):
        # a row breaking two rules carries both reasons, not just the first
        self.assertEqual(check_row({"shipment_id": "", "weight_kg": "-1"}),
                         ["shipment_id_missing", "weight_kg_out_of_range"])


if __name__ == "__main__":
    unittest.main()
